// 7 ngày vừa qua, tính theo giờ Việt Nam: từ 00:00 bảy ngày trước đến 00:00 hôm nay
const end = DateTime.now().setZone('Asia/Ho_Chi_Minh').startOf('day');
const start = end.minus({ days: 7 });
const prevStart = end.minus({ days: 14 });
const last = end.minus({ days: 1 });
return [{ json: { start: start.toISO(), end: end.toISO(), prevStart: prevStart.toISO(),
  startDate: start.toFormat('yyyy-MM-dd'), endDate: last.toFormat('yyyy-MM-dd'),
  label: `${start.toFormat('dd/MM')} - ${last.toFormat('dd/MM/yyyy')}` } }];

const period = $('Kỳ báo cáo').first().json;
const cur = $('Số liệu tuần này').first().json;
const prev = $input.first().json;
const n = x => Number(x ?? 0);
const pct = (a, b) => (n(b) > 0 ? Math.round((n(a) / n(b)) * 1000) / 10 : null);
const funnel = {
  leadToConfirmed: pct(cur.confirmed, cur.new_leads),
  confirmedToViewed: pct(cur.viewed, cur.confirmed),
  viewedToDeposit: pct(cur.deposits, cur.viewed),
  depositToSigned: pct(cur.signed, cur.deposits),
  leadToSigned: pct(cur.signed, cur.new_leads),
};
const keys = ['new_leads', 'confirmed', 'viewed', 'no_show', 'deposits', 'signed', 'lost', 'expired', 'campaign_warm', 'campaign_cold', 'hot_followup'];
const delta = Object.fromEntries(keys.map(k => [k, n(cur[k]) - n(prev[k])]));

// FE-23: Cơ cấu nguồn khách (chuẩn hoá object)
const parseSources = val => {
  if (!val) return {};
  if (typeof val === 'object') return val;
  try { return JSON.parse(val); } catch { return {}; }
};
const curSources = parseSources(cur.sources_breakdown);
const prevSources = parseSources(prev.sources_breakdown);
const allSourceKeys = Array.from(new Set([...Object.keys(curSources), ...Object.keys(prevSources)]));
const sources = {};
for (const k of allSourceKeys) {
  sources[k] = {
    current: n(curSources[k]),
    previous: n(prevSources[k]),
    delta: n(curSources[k]) - n(prevSources[k]),
    rate: pct(curSources[k], cur.new_leads),
  };
}

// FE-23: Số liệu chiến dịch nuôi dưỡng (Mautic & Follow-up)
const campaigns = {
  warm_nurtured: n(cur.campaign_warm),
  cold_nurtured: n(cur.campaign_cold),
  hot_nudged: n(cur.hot_followup),
};

// Cảnh báo bằng quy tắc cố định: không nhờ AI đoán, để lần nào cũng nhất quán
const alerts = [];
if (n(prev.new_leads) >= 3 && n(cur.new_leads) < n(prev.new_leads) * 0.7) {
  alerts.push(`Khách mới giảm ${Math.round((1 - n(cur.new_leads) / n(prev.new_leads)) * 100)}% so với tuần trước (${n(prev.new_leads)} xuống ${n(cur.new_leads)}).`);
}
// Cảnh báo nguồn marketing giảm mạnh (> 50% khi tuần trước có từ 3 khách)
for (const [srcName, srcData] of Object.entries(sources)) {
  if (srcData.previous >= 3 && srcData.current < srcData.previous * 0.5) {
    alerts.push(`Nguồn khách ${srcName} giảm ${Math.round((1 - srcData.current / srcData.previous) * 100)}% so với tuần trước (${srcData.previous} xuống ${srcData.current}).`);
  }
}
if (n(cur.deposits) > 0 && n(cur.signed) === 0) alerts.push(`Có ${n(cur.deposits)} hợp đồng đặt cọc được tạo nhưng chưa có hợp đồng nào được ký.`);
if (n(cur.avg_approval_minutes) > 1440) alerts.push(`Thời gian duyệt lịch trung bình ${Math.round(n(cur.avg_approval_minutes) / 60)} giờ, vượt 24 giờ.`);
if (n(cur.failed_automation) > 0) alerts.push(`${n(cur.failed_automation)} khách bị lỗi xử lý tự động (n8n báo FAILED).`);
if (n(cur.stale_pending) > 0) alerts.push(`Hiện có ${n(cur.stale_pending)} khách đã chấm điểm nhưng chưa được duyệt lịch quá 24 giờ.`);
if (cur.avg_rating !== null && n(cur.feedbacks) >= 2 && n(cur.avg_rating) < 3.5) alerts.push(`Điểm hài lòng trung bình sau buổi xem chỉ ${cur.avg_rating}/5.`);

const report = { period: period.label, cur, prev, delta, funnel, sources, campaigns };
return [{ json: { period, report, alerts } }];

