const base = $('Tính phễu và cảnh báo').first().json;
const out = $input.first().json.output ?? {};
const clean = a => (Array.isArray(a) ? a.map(x => String(x).trim().slice(0, 300)).filter(Boolean).slice(0, 6) : []);
let headline = String(out.headline ?? '').trim().slice(0, 200);
let insights = clean(out.insights);
let recommendations = clean(out.recommendations);
const aiUsed = !!headline && insights.length > 0 && recommendations.length > 0;
if (!aiUsed) { // AI lỗi hoặc trả thiếu: vẫn có báo cáo tối thiểu từ số liệu
  const c = base.report.cur;
  headline = `Tuần ${base.report.period}: ${c.new_leads} khách mới, ${c.signed} hợp đồng đã ký.`;
  insights = [`Khách mới: ${c.new_leads} (chênh ${base.report.delta.new_leads >= 0 ? '+' : ''}${base.report.delta.new_leads} so với tuần trước).`,
              `Đã chốt lịch ${c.confirmed}, đã xem nhà ${c.viewed}, đặt cọc ${c.deposits}, đã ký ${c.signed}.`];
  if (base.report.sources && Object.keys(base.report.sources).length > 0) {
    const topSrc = Object.entries(base.report.sources).sort((a,b) => b[1].current - a[1].current)[0];
    if (topSrc && topSrc[1].current > 0) {
      insights.push(`Nguồn khách hàng đầu tuần này là ${topSrc[0]} với ${topSrc[1].current} khách.`);
    }
  }
  recommendations = base.alerts.length ? base.alerts.map(a => 'Xử lý: ' + a) : ['Duy trì nhịp chăm sóc khách hiện tại.'];
}
return [{ json: { ...base, analysis: { headline, insights, recommendations, aiUsed } } }];

const k = $('Kiểm tra AI').first().json;
const id = $input.first().json.id;
const web = $('Cấu hình').first().json.webUrl;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const c = k.report.cur, p = k.report.prev, d = k.report.delta, f = k.report.funnel;
const money = v => Number(v ?? 0).toLocaleString('vi-VN') + ' đ';
const sign = v => (v > 0 ? '+' + v : String(v));
const pc = v => (v === null || v === undefined ? '-' : v + '%');
const row = (label, a, b, dl) => `<tr><td style="padding:8px 10px">${label}</td><td style="padding:8px 10px;text-align:right"><b>${a}</b></td><td style="padding:8px 10px;text-align:right;color:#6b7280">${b}</td><td style="padding:8px 10px;text-align:right;color:${dl > 0 ? '#16a34a' : dl < 0 ? '#dc2626' : '#6b7280'}">${dl === null ? '' : sign(dl)}</td></tr>`;
const li = arr => arr.map(x => `<li>${esc(x)}</li>`).join('');
const alertsHtml = k.alerts.length ? `<div style="margin-top:16px;padding:12px 16px;background:#fef2f2;border-radius:8px"><b style="color:#b91c1c">Điểm bất thường (${k.alerts.length})</b><ul style="margin:8px 0 0">${li(k.alerts)}</ul></div>` : '';

// FE-23: Nguồn khách và chiến dịch trong email
const srcEntries = Object.entries(k.report.sources || {});
const srcSummary = srcEntries.length
  ? srcEntries.map(([s, val]) => `${esc(s)}: <b>${val.current}</b> (${val.rate ?? 0}%)`).join(' · ')
  : 'Chưa có thông tin';
const camp = k.report.campaigns || {};
const campSummary = `Nuôi WARM: <b>${camp.warm_nurtured ?? 0}</b> · Bản tin COLD: <b>${camp.cold_nurtured ?? 0}</b> · Nhắc HOT: <b>${camp.hot_nudged ?? 0}</b>`;

const html = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden">
<div style="background:#2563eb;color:#fff;padding:20px;font-size:20px;font-weight:bold">Báo cáo kinh doanh tuần ${esc(k.report.period)}</div>
<div style="padding:24px;color:#111827;line-height:1.7;font-size:15px">
<p style="margin-top:0;font-size:17px"><b>${esc(k.analysis.headline)}</b></p>
<table style="width:100%;border-collapse:collapse;background:#f3f4f6"><tr style="color:#6b7280;font-size:13px"><td style="padding:8px 10px"></td><td style="padding:8px 10px;text-align:right">Tuần này</td><td style="padding:8px 10px;text-align:right">Tuần trước</td><td style="padding:8px 10px;text-align:right">Chênh</td></tr>
${row('Khách mới', c.new_leads, p.new_leads, d.new_leads)}${row('Đã chốt lịch', c.confirmed, p.confirmed, d.confirmed)}${row('Đã xem nhà', c.viewed, p.viewed, d.viewed)}${row('Khách không đến', c.no_show ?? 0, p.no_show ?? 0, d.no_show)}${row('Tạo hợp đồng cọc', c.deposits, p.deposits, d.deposits)}${row('Đã ký', c.signed, p.signed, d.signed)}${row('Không mua', c.lost, p.lost, d.lost)}${row('Quá hạn không xử lý (EXPIRED)', c.expired ?? 0, p.expired ?? 0, d.expired ?? 0)}</table>
<p style="margin:12px 0 0;color:#374151">Tiền cọc đã ký: <b>${money(c.signed_amount)}</b> · Chốt lịch ${pc(f.leadToConfirmed)} · Xem nhà ${pc(f.confirmedToViewed)} · Đặt cọc ${pc(f.viewedToDeposit)} · Ký ${pc(f.depositToSigned)}</p>
<div style="margin-top:12px;padding:10px 14px;background:#f8fafc;border-radius:6px;font-size:14px;color:#334155;border:1px solid #e2e8f0">
  <div style="margin-bottom:4px"><b>Nguồn khách:</b> ${srcSummary}</div>
  <div><b>Chiến dịch nuôi dưỡng (Mautic):</b> ${campSummary}</div>
</div>
${alertsHtml}
<p style="margin:16px 0 4px"><b>Nhận định${k.analysis.aiUsed ? '' : ' (AI không khả dụng, dùng mẫu từ số liệu)'}</b></p><ul style="margin:0">${li(k.analysis.insights)}</ul>
<p style="margin:16px 0 4px"><b>Đề xuất cho tuần tới</b></p><ul style="margin:0">${li(k.analysis.recommendations)}</ul>
<p style="margin-top:20px"><a href="${web}/admin/bao-cao?id=${id}" style="background:#2563eb;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;font-weight:bold">Xem trên web</a></p>
</div><div style="background:#f9fafb;padding:12px 24px;color:#9ca3af;font-size:12px">Báo cáo tự động từ hệ thống RealEstate AI.</div></div>`;
return [{ json: { reportId: id, subject: `[BÁO CÁO TUẦN] ${k.report.period}: ${c.new_leads} khách mới, ${c.signed} đã ký${k.alerts.length ? ', ' + k.alerts.length + ' cảnh báo' : ''}`, html,
  alertSubject: `[CẢNH BÁO] Tuần ${k.report.period}: ${k.alerts.length} điểm bất thường`,
  alertHtml: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto"><h2 style="color:#b91c1c">Có ${k.alerts.length} điểm bất thường trong tuần ${esc(k.report.period)}</h2><ul>${li(k.alerts)}</ul><p><a href="${web}/admin/bao-cao?id=${id}">Xem báo cáo đầy đủ</a></p></div>` } }];
